// DeleteRentalItem is the resolver for the deleteRentalItem field.
func (r *mutationResolver) DeleteRentalItem(ctx context.Context, id string) (bool, error) {
	var inventory model.InventoryItem

	// Find the inventory item
	if err := r.DB.First(&inventory, "id = ?", id).Error; err != nil {
		return false, fmt.Errorf("inventory item not found: %w", err)
	}

	// Delete file from MinIO if it exists
	if inventory.ImageURL != nil {
		if inventory.ServiceID == nil {
			return false, fmt.Errorf("missing service ID for file deletion")
		}

		// Derive bucket name
		bucketName := fmt.Sprintf("service-%s-bucket", inventory.ServiceID)

		// Extract object name from ImageURL
		objectName, err := helper.ExtractObjectNameFromURL(*inventory.ImageURL)
		if err != nil {
			return false, fmt.Errorf("failed to extract object name from image URL: %w", err)
		}

		// Delete from MinIO
		if err := r.MinIOClient.RemoveObject(ctx, bucketName, objectName, minio.RemoveObjectOptions{}); err != nil {
			return false, fmt.Errorf("failed to delete file from MinIO: %w", err)
		}
	}

	// Delete from DB
	if err := r.DB.Delete(&inventory).Error; err != nil {
		return false, fmt.Errorf("failed to delete inventory item: %w", err)
	}

	return true, nil
}

// UpdateInventoryItem is the resolver for the updateInventoryItem field.
func (r *mutationResolver) UpdateInventoryItem(ctx context.Context, id string, input model.InventoryItemInput, file graphql.Upload) (*model.InventoryItem, error) {
	var item model.InventoryItem

	// Fetch existing item
	if err := r.DB.First(&item, "id = ?", id).Error; err != nil {
		return nil, fmt.Errorf("inventory item not found: %w", err)
	}

	// Update basic fields
	item.Name = input.Name
	item.Description = input.Description
	item.Price = input.Price
	item.Available = input.Available

	// Update category if provided
	// if input.CategoryID != "" {
	// 	item.CategoryID = input.CategoryID
	// }

	// If file is provided and has size > 0, replace image
	if file.Size > 0 {
		simpleName := strings.ToLower(strings.ReplaceAll(*item.ServiceID, "-", ""))
		bucketName := fmt.Sprintf("s-%s", simpleName[:helper.MinInt(len(simpleName), 10)])

		// Ensure the bucket exists
		if err := helper.CreateBucketInMinio(ctx, r.MinIOClient, bucketName); err != nil {
			return nil, err
		}

		// Upload the new file
		fileURL, err := helper.UploadFileToMinio(ctx, r.MinIOClient, bucketName, "inventory", &file)
		if err != nil {
			return nil, fmt.Errorf("failed to upload file: %w", err)
		}

		item.ImageURL = &fileURL
	}

	// Save the updated item
	if err := r.DB.Save(&item).Error; err != nil {
		return nil, fmt.Errorf("failed to update inventory item: %w", err)
	}

	return &item, nil
}

