// GetRentalItems is the resolver for the getRentalItems field.
func (r *queryResolver) GetRentalItems(ctx context.Context, serviceID *string) ([]*model.RentalItem, error) {
	var inventoryItems []*model.InventoryItem

	if serviceID != nil {
		if err := r.DB.Where("service_id = ?", *serviceID).Find(&inventoryItems).Error; err != nil {
			return nil, fmt.Errorf("failed to get inventory items for service ID: %w", err)
		}
	} else {
		if err := r.DB.Find(&inventoryItems).Error; err != nil {
			return nil, fmt.Errorf("failed to get all inventory items: %w", err)
		}
	}

	// Group items by category
	categoryMap := make(map[string]*model.RentalItem)
	for _, item := range inventoryItems {
		var category model.Category
		if err := r.DB.First(&category, "id = ?", item.CategoryID).Error; err != nil {
			return nil, fmt.Errorf("failed to get category: %w", err)
		}

		if _, exists := categoryMap[category.ID.String()]; !exists {
			categoryMap[category.ID.String()] = &model.RentalItem{
				Category:    &category,
				Inventories: []*model.InventoryItem{},
			}
		}
		categoryMap[category.ID.String()].Inventories = append(categoryMap[category.ID.String()].Inventories, item)
	}

	var rentalItems []*model.RentalItem
	for _, rental := range categoryMap {
		rentalItems = append(rentalItems, rental)
	}

	return rentalItems, nil
}

